head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pageNoCnt = 10; // page 번호 개수
scwin.vCurrPageNo = 0; // 현재 선택된 페이지번호
scwin.vPAGENO = 0;
// 화면 리사이징

scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gIsurCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.setCode();
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
        scwin.init();
        if (scwin.gLdMktTp !== "9") {
            label_3.style.display = "none";
            cmb_CORP_USR_TP_CD.style.display = "none";
        }
        await scwin.listRoadZipCdAppl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF34001.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    // 한달전 날짜
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDATE.setValue($c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 1)); // 한달전 날짜
    edt_EDATE.setValue($c.ut.cGetToday2());
    rdo_MKT_ID.setValue(js_market);
    if (js_market !== "9") {
        panel_mkt.hide();
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listRoadZipCdAppl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF34001.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_SDATE_onclick
 * @description btn_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDATE_onclick = function() {
    try {
        popUpCalendar2(edt_SDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.btn_SDATE_onclick" });
    }
};

/**
 * @method
 * @name btn_EDATE_onclick
 * @description btn_EDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDATE_onclick = function() {
    try {
        popUpCalendar2(edt_EDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.btn_EDATE_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = cmb_PeriodTp.getValue();
        $c.stf.setFromToDate(vTp, edt_SDATE, edt_EDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF34001.xml", SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "본점소재지 도로명주소 변경신청 목록", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name cmb_PerPage_onselchange
 * @description cmb_PerPage onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PerPage_onselchange = function() {
    try {
        scwin.vCurrPageNo = 1;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.cmb_PerPage_onselchange" });
    }
};

/**
 * @method
 * @name dts_RoadZipCdApplList_OnLoadCompleted
 * @description dts_RoadZipCdApplList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_RoadZipCdApplList_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.vPAGENO === 0) {
            scwin.vCurrPageNo = 1;
        }
        const vTotalCnt = dts_RoadZipCdApplList.getCellData(1, "CNT");
        $c.stf.FillGridHeader2(scwin.pageNoCnt, cmb_PerPage.getValue(), vTotalCnt, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.dts_RoadZipCdApplList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_RoadZipCdApplList_OnLoadError
 * @description dts_RoadZipCdApplList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_RoadZipCdApplList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_RoadZipCdApplList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF34001.dts_RoadZipCdApplList_OnLoadError" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        await scwin.readRoadZipCdAppl(row, colid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF34001.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_ISUR_CD_onclick
 * @description btn_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISUR_CD_onclick = function() {
    try {
        // 2009.09.01 채권공시관련 - 채권법인검색창
        if (js_bond_yn === "Y") {
            $c.cm.IsurcdSearchBond(txb_ISUR_CD, txb_COM_NM);
        } else {
            $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.btn_ISUR_CD_onclick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name dts_emp_OnLoadError
 * @description dts_emp 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_emp_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_emp);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF34001.dts_emp_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_dep_OnLoadError
 * @description dts_dep 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_dep_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_dep);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF34001.dts_dep_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_dep_OnLoadCompleted
 * @description dts_dep 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    try {
        cmb_TeamList.setValue(scwin.gDepCd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.dts_dep_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_emp_OnLoadCompleted
 * @description dts_emp 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    try {
        cmb_EmpList.setValue(scwin.gEmpNo);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.dts_emp_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name cmb_TeamList_onselchange
 * @description cmb_TeamList onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_TeamList_onselchange = function() {
    try {
        scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
        if (scwin.gDepCd === '') {
            cmb_EmpList.setValue('');
        }
        dts_emp.UseFilter = true;
        dts_emp.Filter();
        dts_emp.sort("DEP_CD", 0);
        // dts_emp.sort(); // W-Craft 주석처리
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.cmb_TeamList_onselchange" });
    }
};

/**
 * @method
 * @name cmb_EmpList_onselchange
 * @description cmb_EmpList onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_EmpList_onselchange = function() {
    try {
        scwin.gEmpNo = cmb_EmpList.getValue();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.cmb_EmpList_onselchange" });
    }
};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description emp On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_emp.getCellData(row, "dep_cd") === scwin.gDepCd ||
                dts_emp.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF34001.dts_emp_OnFilter" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listRoadZipCdAppl
 * @description list Road Zip Cd Appl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listRoadZipCdAppl = async function() {
    const argv = scwin.listRoadZipCdAppl.arguments;
    const argc = scwin.listRoadZipCdAppl.arguments.length;
    scwin.vPAGENO = (argc === 0) ? 0 : scwin.vPAGENO = argv[0];
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&COM_NM=" + txb_COM_NM.getValue();
    url += "&SDATE=" + edt_SDATE.getValue();
    url += "&EDATE=" + edt_EDATE.getValue();
    url += "&APPL_RSLT=" + cmb_APPL_RSLT.getValue();
    url += "&DEP_CD=" + scwin.gDepCd;
    url += "&EMP_NO=" + scwin.gEmpNo;
    url += "&SCREN_ID=" + "ULDSTF34001.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    if (scwin.gLdMktTp === "1") {
        url += "&CORP_USR_TP_CD=11";
    } else if (scwin.gLdMktTp === "2") {
        url += "&CORP_USR_TP_CD=21";
    } else if (scwin.gLdMktTp === "4") {
        url += "&CORP_USR_TP_CD=19";
    } else if (scwin.gLdMktTp === "6") {
        url += "&CORP_USR_TP_CD=61";
    } else {
        url += "&CORP_USR_TP_CD=" + cmb_CORP_USR_TP_CD.getValue();
    }
    url += "&PAGENO=" + scwin.vPAGENO;
    url += "&PAGESIZE=" + cmb_PerPage.getValue();
    const sbmOptions = {
        id : "sbm_dts_RoadZipCdApplList",
        action : "/ListedCompanyPassword.do",
        ref : "",
        target : "dts_RoadZipCdApplList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    $c.stf.comboCbDataSet(cmb_PerPage);
    cmb_APPL_RSLT.setValue("R");
    const sbmOptions3 = {
        id : "sbm_dts_CORP_USR_TP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_CORP_USR_TP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 채권상장팀의 경우 팀선택 및 팀원선택박스 '전체' 로 디폴트 갖도록 변경.  20130912 by LDJ(송은진과장님 요청사항)
    if (js_bond_yn === "Y") {
        scwin.gDepCd = '';
        scwin.gEmpNo = '';
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name PageNoCall
 * @description Page No Call 처리
 * @param {*} vPageNo vPageNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.PageNoCall = async function(vPageNo) {
    scwin.vCurrPageNo = vPageNo;
    await scwin.listRoadZipCdAppl(vPageNo);
};

/**
 * @method
 * @name readRoadZipCdAppl
 * @description read Road Zip Cd Appl 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readRoadZipCdAppl = async function(row, colid) {
    if (colid === "CHG_PROCS_STAT_CD_NM") {
        // 처리현황 클릭 시
        gISUR_CD = dts_RoadZipCdApplList.getCellData(Number(row), "ISUR_CD");
        gLD_MKT_TP_CD = dts_RoadZipCdApplList.getCellData(Number(row), "LD_MKT_TP_CD");
        gCORP_USR_TP_CD = dts_RoadZipCdApplList.getCellData(Number(row), "CORP_USR_TP_CD");
        gADDR_CHG_TP_CD = dts_RoadZipCdApplList.getCellData(Number(row), "ADDR_CHG_TP_CD");
        gSEQ = dts_RoadZipCdApplList.getCellData(Number(row), "SEQ");
        gCOM_ABBRV = dts_RoadZipCdApplList.getCellData(Number(row), "COM_ABBRV");
        gCORP_USR_TP_CD_NM = dts_RoadZipCdApplList.getCellData(Number(row), "CORP_USR_TP_CD_NM");
        gAPPL_DDTM = dts_RoadZipCdApplList.getCellData(Number(row), "APPL_DDTM");
        gBFCHG_ZIPCD = dts_RoadZipCdApplList.getCellData(Number(row), "BFCHG_ZIPCD");
        gBF_ADDR = dts_RoadZipCdApplList.getCellData(Number(row), "BF_ADDR");
        gAFCHG_ZIPCD = dts_RoadZipCdApplList.getCellData(Number(row), "AFCHG_ZIPCD");
        gAF_ADDR = dts_RoadZipCdApplList.getCellData(Number(row), "AF_ADDR");
        gCHG_PROCS_STAT_CD = dts_RoadZipCdApplList.getCellData(Number(row), "CHG_PROCS_STAT_CD");
        let url = "/issueinfo/ULDSTF34002.gfm";
        const winTitle = "상장법인 본점소재지 도로명주소 변경신청 처리";
        await $c.frame.CreateDialogFrame("ULDSTF37407", url, winTitle, 100, 100, 730, 350, "window");
    } else if (colid === "COM_ABBRV") {
        scwin.gIsurCd = dts_RoadZipCdApplList.getCellData(row, "ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    } else if (colid === "ATTACH_FILE_NM") {
        seq = dts_RoadZipCdApplList.getCellData(row, "SEQ");
        // alert(seq);
        scwin.filedown(seq);
    }
};

/**
 * @method
 * @name filedown
 * @description 파일 다운로드
 * @param {*} attach_seq attach_seq
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function(attach_seq) {
    location.href = "/filedownload.do?attach_seq=" + attach_seq + "&gubun=29";
};
